from taf.selenium.gnb.oam.coam.classical import classical
from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector
from taf.rfrl.procedures.resources.python.webui.engine import Engine


class GnbEngine(Engine):

    def __init__(self, sw_stream):
        super(Engine, self).__init__()
        self._api = classical()
        self._sw_stream = sw_stream

    def __str__(self):
        return "GnbEngine webui instance for {0} stream".format(self._sw_stream)

    @log_input_and_output
    def login(self, url, username, password, screenshot_dir, download_dir, browser, sync_full_rack=False):
        """
        Logs in and disables message box

        :param url: url
        :type url: str
        :param username: username to log in
        :type username: str
        :param password: password to log in
        :type password: str
        :param screenshot_dir: directory where the screenshots will be saved
        :type screenshot_dir: str
        :param download_dir: directory for downloading files
        :type download_dir: str
        :param browser: WebDriver instance or "Chrome" or "Firefox" or alias name for self-created webdriver
        :type browser: Optional[WebDriver, str]
        :param sync_full_rack: states if full rack synchronization should be performed
        :type sync_full_rack: bool
        """
        self._api.login(url=url, username=username, password=password, screenshot_dir=screenshot_dir,
                        download_dir=download_dir, browser=browser, version=self._sw_stream)
        self._api.disable_message_box()

    @log_input_and_output
    def lock_cell(self, cell_id, timeout):
        """
        Locks cell
        :param cell_id: index of cell to be locked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.lock_cell(cell_idx=cell_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_is_locked(self, cell_id):
        """
        Checks if cell is locked by its statuses
        :param cell_id: index of cell
        :type cell_id: int
        :return: True if cell is locked, False otherwise
        :rtype: boolean
        """
        cell_info = self._api.get_cell_info(cell_idx=cell_id)
        oper_state = cell_info['Status']['Operational state']
        av_status = cell_info['Status'].get('Availability status', None)
        adm_state = cell_info['Status']['Administrative state']

        status_selector = StatusSelector()
        disabled = status_selector.select_operational_state(variant='disabled')
        offline = status_selector.select_availability_status(variant='offline')
        locked = status_selector.select_administrative_state(variant='locked')

        return oper_state == disabled and av_status == offline and adm_state == locked

    @log_input_and_output
    def unlock_cell(self, cell_id, timeout):
        """
        Unlocks cell
        :param cell_id: index of cell to be unlocked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.unlock_cell(cell_idx=cell_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_is_unlocked(self, cell_id):
        """
        Checks if cell is unlocked by its statuses
        :param cell_id: index of cell
        :type cell_id: int
        :return: True if cell is unlocked, False otherwise
        :rtype: boolean
        """
        cell_info = self._api.get_cell_info(cell_idx=cell_id)
        oper_state = cell_info['Status']['Operational state']
        av_status = cell_info['Status'].get('Availability status', None)
        adm_state = cell_info['Status']['Administrative state']

        status_selector = StatusSelector()
        enabled = status_selector.select_operational_state(variant='enabled')
        online = status_selector.select_availability_status(variant='online')
        unlocked = status_selector.select_administrative_state(variant='unlocked')

        return oper_state == enabled and av_status == online and adm_state == unlocked

    @log_input_and_output
    def lock_cell_group(self, cell_group_id, timeout):
        """
        Locks cell group
        :param cell_group_id: index of cell group to be locked
        :type cell_group_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.lock_cell_group(cell_group_idx=cell_group_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_group_is_locked(self, cell_group_id):
        """
        Checks if cell group is locked
        :param cell_group_id: index of cell group
        :type cell_group_id: int
        :return: True if cell group is locked, False otherwise
        :rtype: boolean
        """
        cell_grp_status = self._api.get_cell_group_status(cell_group_idx=cell_group_id)
        return cell_grp_status == 'Locked'

    @log_input_and_output
    def unlock_cell_group(self, cell_group_id, timeout):
        """
        Unlocks cell group
        :param cell_group_id: index of cell group to be locked
        :type cell_group_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.unlock_cell_group(cell_group_idx=cell_group_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_group_is_unlocked(self, cell_group_id):
        """
        Checks if cell group is unlocked
        :param cell_group_id: index of cell group
        :type cell_group_id: int
        :return: True if cell group is unlocked, False otherwise
        :rtype: boolean
        """
        cell_grp_status = self._api.get_cell_group_status(cell_group_idx=cell_group_id)
        return cell_grp_status == 'Unlock'
